$ErrorActionPreference = "Stop"

Write-Host "=== SaborFlow - Etapa 13.4 Passkeys / WebAuthn ===" -ForegroundColor Cyan
Write-Host ""

if (-not (Test-Path "package.json")) {
    throw "Execute este script na pasta principal do projeto SaborFlow."
}

if (-not (Test-Path "database\migrations\029_admin_2fa_recovery_management.sql")) {
    throw "A Etapa 13.3 nao foi encontrada. A migration 029 precisa existir antes da 13.4."
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path $env:TEMP "SaborFlow-Etapa13-4-Backup-$timestamp"
New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null

$targets = @(
    "package.json",
    "package-lock.json",
    "components\admin\login-form.tsx",
    "components\admin\security-panel.tsx",
    "database\migrations\030_admin_passkeys.sql",
    "lib\security\passkey-challenge.ts",
    "lib\security\passkeys.ts",
    "app\api\admin\passkeys\route.ts",
    "app\api\admin\passkeys\register\options\route.ts",
    "app\api\admin\passkeys\register\verify\route.ts",
    "app\api\auth\passkey\options\route.ts",
    "app\api\auth\passkey\verify\route.ts",
    "app\api\auth\logout\route.ts",
)

foreach ($file in $targets) {
    if (Test-Path $file) {
        $backupPath = Join-Path $backupRoot $file
        $backupDir = Split-Path $backupPath -Parent
        New-Item -ItemType Directory -Force -Path $backupDir | Out-Null
        Copy-Item $file $backupPath -Force
    }
}

Write-Host "Backup criado em:" -ForegroundColor Green
Write-Host $backupRoot
Write-Host ""

Write-Host "Instalando SimpleWebAuthn 13.1.2..." -ForegroundColor Cyan
& npm.cmd install "@simplewebauthn/server@13.1.2" "@simplewebauthn/browser@13.1.2" --save-exact

if ($LASTEXITCODE -ne 0) {
    Write-Host "Falha na instalacao. Restaurando package.json/package-lock.json..." -ForegroundColor Red

    foreach ($file in @("package.json", "package-lock.json")) {
        $backupPath = Join-Path $backupRoot $file
        if (Test-Path $backupPath) {
            Copy-Item $backupPath $file -Force
        }
    }

    throw "npm install falhou. Nenhum arquivo da Etapa 13.4 foi gravado."
}

function Write-Base64File {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$Base64
    )

    $directory = Split-Path $Path -Parent

    if ($directory) {
        New-Item -ItemType Directory -Force -Path $directory | Out-Null
    }

    $bytes = [Convert]::FromBase64String($Base64)
    [IO.File]::WriteAllBytes(
        (Join-Path (Get-Location) $Path),
        $bytes
    )
}

Write-Host "Gravando components\admin\login-form.tsx..."
Write-Base64File -Path "components\admin\login-form.tsx" -Base64 ""

Write-Host "Gravando components\admin\security-panel.tsx..."
Write-Base64File -Path "components\admin\security-panel.tsx" -Base64 ""

Write-Host "Gravando database\migrations\030_admin_passkeys.sql..."
Write-Base64File -Path "database\migrations\030_admin_passkeys.sql" -Base64 ""

Write-Host "Gravando lib\security\passkey-challenge.ts..."
Write-Base64File -Path "lib\security\passkey-challenge.ts" -Base64 ""

Write-Host "Gravando lib\security\passkeys.ts..."
Write-Base64File -Path "lib\security\passkeys.ts" -Base64 ""

Write-Host "Gravando app\api\admin\passkeys\route.ts..."
Write-Base64File -Path "app\api\admin\passkeys\route.ts" -Base64 ""

Write-Host "Gravando app\api\admin\passkeys\register\options\route.ts..."
Write-Base64File -Path "app\api\admin\passkeys\register\options\route.ts" -Base64 ""

Write-Host "Gravando app\api\admin\passkeys\register\verify\route.ts..."
Write-Base64File -Path "app\api\admin\passkeys\register\verify\route.ts" -Base64 ""

Write-Host "Gravando app\api\auth\passkey\options\route.ts..."
Write-Base64File -Path "app\api\auth\passkey\options\route.ts" -Base64 ""

Write-Host "Gravando app\api\auth\passkey\verify\route.ts..."
Write-Base64File -Path "app\api\auth\passkey\verify\route.ts" -Base64 ""

Write-Host "Gravando app\api\auth\logout\route.ts..."
Write-Base64File -Path "app\api\auth\logout\route.ts" -Base64 ""


Write-Host ""
Write-Host "Etapa 13.4 aplicada localmente." -ForegroundColor Green
Write-Host "Incluido:" -ForegroundColor Green
Write-Host " - Passkeys como segundo fator alternativo ao codigo de 6 digitos"
Write-Host " - Windows Hello / biometria / Passkeys sincronizadas"
Write-Host " - chaves fisicas FIDO2 / USB / NFC compativeis"
Write-Host " - cadastro e remocao protegidos pelo 2FA atual"
Write-Host " - multiplas Passkeys por usuario (limite 10)"
Write-Host " - desafio WebAuthn assinado, temporario e vinculado ao login atual"
Write-Host " - Superadmin continua dependendo do login principal por CPF"
Write-Host " - Authenticator e codigos de recuperacao continuam como fallback"
Write-Host ""
Write-Host "IMPORTANTE: a migration 030 foi apenas criada. Ela NAO foi executada no banco." -ForegroundColor Yellow
Write-Host "Nenhum commit ou deploy foi feito." -ForegroundColor Yellow
Write-Host ""
Write-Host "Versoes instaladas:" -ForegroundColor Cyan
& npm.cmd ls "@simplewebauthn/server" "@simplewebauthn/browser" next --depth=0
Write-Host ""
git status --short
